export type WireErrorCode =
  | "short_buffer"
  | "overflow"
  | "invalid_bool"
  | "invalid_enum"
  | "invalid_tag"
  | "invalid_version"
  | "invalid_const"
  | "invalid_mask"
  | "non_zero_padding"
  | "limit_exceeded"
  | "buffer_full";

export class WireError extends Error {
  readonly code: WireErrorCode;

  constructor(code: WireErrorCode, message: string) {
    super(message);
    this.name = "WireError";
    this.code = code;
  }
}

export const EMPTY_BYTES: Uint8Array = new Uint8Array(0);

