const U64_MAX = 0xffffffffffffffffn;

function leadingZeros64(x: bigint): number {
  let v = BigInt.asUintN(64, x);
  if (v === 0n) return 64;
  let n = 0;
  if (v <= 0x00000000ffffffffn) { n += 32; v <<= 32n; }
  if (v <= 0x0000ffffffffffffn) { n += 16; v <<= 16n; }
  if (v <= 0x00ffffffffffffffn) { n += 8; v <<= 8n; }
  if (v <= 0x0fffffffffffffffn) { n += 4; v <<= 4n; }
  if (v <= 0x3fffffffffffffffn) { n += 2; v <<= 2n; }
  if (v <= 0x7fffffffffffffffn) { n += 1; }
  return n;
}

function isFloat32NaN(u: number): boolean {
  return (u & 0x7f800000) === 0x7f800000 && (u & 0x007fffff) !== 0;
}

function isFloat32Finite(u: number): boolean {
  return (u & 0x7f800000) !== 0x7f800000;
}

function float32Order(u: number): number {
  const bits = u >>> 0;
  if (bits === 0x80000000) return 0;
  if ((bits & 0x80000000) !== 0) return -(bits & 0x7fffffff);
  return bits;
}

function decomposeFloat32(u: number): [boolean, bigint, number] {
  const bits = u >>> 0;
  const neg = (bits >>> 31) !== 0;
  const e = (bits >>> 23) & 0xff;
  const f = BigInt(bits & 0x7fffff);
  let sig: bigint;
  let exp: number;
  if (e === 0) {
    if (f === 0n) return [false, 0n, 0];
    sig = f;
    exp = -149;
  } else {
    sig = (1n << 23n) | f;
    exp = e - 150;
  }
  const lz = leadingZeros64(sig);
  const shift = lz - 40;
  if (shift > 0) {
    sig <<= BigInt(shift);
    exp -= shift;
  }
  return [neg, sig, exp];
}

function subFloat32Pos(ua: number, ub: number): [bigint, number] {
  const [aNeg, aSig, aExp] = decomposeFloat32(ua);
  const [bNegRaw, bSig, bExp] = decomposeFloat32(ub);
  const bNeg = !bNegRaw;
  let resSig: bigint;
  let resExp: number;
  if (bSig === 0n) {
    resSig = aSig;
    resExp = aExp;
  } else if (aSig === 0n) {
    resSig = bSig;
    resExp = bExp;
  } else {
    let hiNeg = aNeg, hiSig = aSig, hiExp = aExp;
    let loNeg = bNeg, loSig = bSig, loExp = bExp;
    if (bExp > aExp || (bExp === aExp && bSig > aSig)) {
      hiNeg = bNeg; hiSig = bSig; hiExp = bExp;
      loNeg = aNeg; loSig = aSig; loExp = aExp;
    }
    const d = hiExp - loExp;
    if (d <= 38) {
      const shifted = hiSig << BigInt(d);
      resSig = hiNeg === loNeg ? shifted + loSig : shifted - loSig;
      resExp = loExp;
    } else {
      const shiftedHi = hiSig << 38n;
      const s = d - 38;
      let shiftedLo = 0n;
      let sticky = 0n;
      if (s >= 64) {
        sticky = 1n;
      } else {
        const sBig = BigInt(s);
        shiftedLo = loSig >> sBig;
        if ((loSig & ((1n << sBig) - 1n)) !== 0n) sticky = 1n;
      }
      resSig = hiNeg === loNeg ? shiftedHi + shiftedLo : shiftedHi - shiftedLo - sticky;
      resExp = hiExp - 38;
    }
  }
  const lz = leadingZeros64(resSig);
  if (lz > 1) {
    const shift = lz - 1;
    resSig <<= BigInt(shift);
    resExp -= shift;
  } else if (lz === 0) {
    resSig >>= 1n;
    resExp += 1;
  }
  return [resSig, resExp];
}

function packFloat32(neg: boolean, sig: bigint, exp: number, sticky: boolean): number {
  if (sig === 0n) return 0;
  const sign = neg ? 0x80000000 : 0;
  const top = 63 - leadingZeros64(sig);
  let unbiased = exp + top;
  if (unbiased > 127) {
    return float32FromBits(sign | 0x7f800000);
  }
  if (unbiased >= -126) {
    let mant: bigint;
    let roundBit = false;
    let st: boolean;
    if (top > 23) {
      const shift = top - 23;
      mant = sig >> BigInt(shift);
      roundBit = ((sig >> BigInt(shift - 1)) & 1n) !== 0n;
      st = sticky || (shift > 1 && (sig & ((1n << BigInt(shift - 1)) - 1n)) !== 0n);
    } else {
      mant = sig << BigInt(23 - top);
      st = sticky;
    }
    if (roundBit && (st || (mant & 1n) !== 0n)) {
      mant += 1n;
      if (mant === (1n << 24n)) {
        mant >>= 1n;
        unbiased += 1;
        if (unbiased > 127) {
          return float32FromBits(sign | 0x7f800000);
        }
      }
    }
    return float32FromBits((sign | ((unbiased + 127) << 23) | Number(mant & 0x7fffffn)) >>> 0);
  }

  const shift = -149 - exp;
  if (shift > 64) {
    return float32FromBits(sign);
  }
  let mant: bigint;
  let roundBit = false;
  let st: boolean;
  if (shift === 64) {
    mant = 0n;
    roundBit = (sig >> 63n) !== 0n;
    st = sticky || (sig & ((1n << 63n) - 1n)) !== 0n;
  } else if (shift > 0) {
    mant = sig >> BigInt(shift);
    roundBit = ((sig >> BigInt(shift - 1)) & 1n) !== 0n;
    st = sticky || (shift > 1 && (sig & ((1n << BigInt(shift - 1)) - 1n)) !== 0n);
  } else {
    mant = sig << BigInt(-shift);
    st = sticky;
  }
  if (roundBit && (st || (mant & 1n) !== 0n)) {
    mant += 1n;
    if (mant === (1n << 23n)) {
      return float32FromBits((sign | (1 << 23)) >>> 0);
    }
  }
  return float32FromBits((sign | Number(mant & 0x7fffffn)) >>> 0);
}

function addSignedToFloat32(
  aNeg: boolean, aSigIn: bigint, aExpIn: number,
  bNeg: boolean, bSigIn: bigint, bExpIn: number, bStickyIn: boolean,
): number {
  let aSig = aSigIn, aExp = aExpIn;
  let bSig = bSigIn, bExp = bExpIn, bSticky = bStickyIn;
  if (aSig === 0n) return packFloat32(bNeg, bSig, bExp, bSticky);
  if (bSig === 0n) return packFloat32(aNeg, aSig, aExp, false);

  const aLz = leadingZeros64(aSig);
  if (aLz > 1) {
    const s = aLz - 1;
    aSig <<= BigInt(s);
    aExp -= s;
  } else if (aLz === 0) {
    aSig >>= 1n;
    aExp += 1;
  }
  const bLz = leadingZeros64(bSig);
  if (bLz > 1) {
    const s = bLz - 1;
    bSig <<= BigInt(s);
    bExp -= s;
  } else if (bLz === 0) {
    bSticky = bSticky || (bSig & 1n) !== 0n;
    bSig >>= 1n;
    bExp += 1;
  }

  let hiNeg = aNeg, hiSig = aSig, hiExp = aExp, hiSticky = false;
  let loNeg = bNeg, loSig = bSig, loExp = bExp, loSticky = bSticky;
  if (bExp > aExp || (bExp === aExp && (bSig > aSig || (bSig === aSig && bSticky)))) {
    hiNeg = bNeg; hiSig = bSig; hiExp = bExp; hiSticky = bSticky;
    loNeg = aNeg; loSig = aSig; loExp = aExp; loSticky = false;
  }

  const d = hiExp - loExp;
  let loShifted: bigint;
  let lostSticky: boolean;
  if (d === 0) {
    loShifted = loSig;
    lostSticky = loSticky;
  } else if (d < 64) {
    const dBig = BigInt(d);
    loShifted = loSig >> dBig;
    lostSticky = loSticky || (loSig & ((1n << dBig) - 1n)) !== 0n;
  } else {
    loShifted = 0n;
    lostSticky = true;
  }

  if (hiNeg === loNeg) {
    return packFloat32(hiNeg, hiSig + loShifted, hiExp, hiSticky || lostSticky);
  }
  if (hiSig === loShifted && !hiSticky && !lostSticky) {
    return 0;
  }
  let diff = hiSig - loShifted;
  let sticky = hiSticky;
  if (lostSticky) {
    if (!hiSticky) diff -= 1n;
    sticky = true;
  }
  if (diff === 0n && !sticky) return 0;
  if (diff === 0n) return packFloat32(hiNeg, 1n, hiExp - 1, true);
  return packFloat32(hiNeg, diff, hiExp, sticky);
}

/**
 * Pure-integer float32 quantization identical bit-for-bit to Go's wire.QuantizeFloat.
 */
export function quantizeFloat(v: number, minVal: number, maxVal: number, bits: number): number {
  if (bits < 1) return 0;
  const b = bits > 32 ? 32 : bits;
  const umin = float32Bits(minVal);
  const umax = float32Bits(maxVal);
  if (!isFloat32Finite(umin) || !isFloat32Finite(umax) || float32Order(umin) >= float32Order(umax)) {
    return 0;
  }
  const uv = float32Bits(v);
  if (isFloat32NaN(uv)) return 0;
  const maxQ = (1n << BigInt(b)) - 1n;
  const ov = float32Order(uv);
  const omin = float32Order(umin);
  const omax = float32Order(umax);
  if (ov <= omin) return 0;
  if (ov >= omax) return Number(maxQ);

  const [nSig, nExp] = subFloat32Pos(uv, umin);
  const [dSig, dExp] = subFloat32Pos(umax, umin);
  const eDiff = dExp - nExp;
  if (eDiff < 0) return Number(maxQ);
  if (eDiff > 34) return 0;

  const prod = nSig * maxQ;
  const q0 = prod / dSig;
  const r0 = prod % dSig;

  let q: bigint;
  if (eDiff === 0) {
    q = q0;
    if ((r0 << 1n) >= dSig) q += 1n;
  } else {
    const eBig = BigInt(eDiff);
    q = q0 >> eBig;
    const lowBits = q0 & ((1n << eBig) - 1n);
    const halfBit = 1n << BigInt(eDiff - 1);
    if (lowBits >= halfBit) q += 1n;
  }
  if (q > maxQ) q = maxQ;
  return Number(q);
}

/**
 * Pure-integer float32 dequantization identical bit-for-bit to Go's wire.DequantizeFloat.
 */
export function dequantizeFloat(q: number, minVal: number, maxVal: number, bits: number): number {
  const umin = float32Bits(minVal);
  const umax = float32Bits(maxVal);
  const minF32 = float32FromBits(umin);
  if (bits < 1) return minF32;
  const b = bits > 32 ? 32 : bits;
  if (!isFloat32Finite(umin) || !isFloat32Finite(umax) || float32Order(umin) >= float32Order(umax)) {
    return minF32;
  }
  const maxQ = (1n << BigInt(b)) - 1n;
  const qBig = BigInt(q >>> 0);
  if (qBig === 0n) return minF32;
  if (qBig >= maxQ) return float32FromBits(umax);

  const [dSig, dExp] = subFloat32Pos(umax, umin);
  const prod = dSig * qBig;
  let offSig = prod / maxQ;
  let offRem = prod % maxQ;
  let offExp = dExp;
  const lz = leadingZeros64(offSig);
  if (lz > 1) {
    const shift = lz - 1;
    const shiftedRem = offRem << BigInt(shift);
    const extraSig = shiftedRem / maxQ;
    offRem = shiftedRem % maxQ;
    offSig = (offSig << BigInt(shift)) | extraSig;
    offExp -= shift;
  }
  const offSticky = offRem !== 0n;
  const [mNeg, mSig, mExp] = decomposeFloat32(umin);
  return addSignedToFloat32(mNeg, mSig, mExp, false, offSig, offExp, offSticky);
}

function isFloat64NaN(u: bigint): boolean {
  return (u & 0x7ff0000000000000n) === 0x7ff0000000000000n && (u & 0x000fffffffffffffn) !== 0n;
}

function scaledFloat64Mag(u: bigint, scale: bigint): [bigint, boolean] {
  const e = Number((u >> 52n) & 0x7ffn);
  const f = u & 0x000fffffffffffffn;
  let sig: bigint;
  let exp: number;
  if (e === 0) {
    if (f === 0n) return [0n, false];
    sig = f;
    exp = -1074;
  } else {
    sig = (1n << 52n) | f;
    exp = e - 1075;
  }
  const prod = sig * scale;
  if (exp >= 0) {
    if (exp >= 64) return [0n, prod !== 0n];
    const val = prod << BigInt(exp);
    if (val > U64_MAX) return [0n, true];
    return [val, false];
  }
  const s = -exp;
  if (s >= 129) return [0n, false];
  let q = prod >> BigInt(s);
  if (q > U64_MAX) return [0n, true];
  if (((prod >> BigInt(s - 1)) & 1n) !== 0n) {
    q += 1n;
    if (q > U64_MAX) return [0n, true];
  }
  return [q, false];
}

function packFloat64(neg: boolean, sig: bigint, exp: number, sticky: boolean): number {
  if (sig === 0n) return 0;
  const sign = neg ? (1n << 63n) : 0n;
  const top = 63 - leadingZeros64(sig);
  let unbiased = exp + top;
  if (unbiased > 1023) {
    return float64FromBits(sign | 0x7ff0000000000000n);
  }
  if (unbiased >= -1022) {
    let mant: bigint;
    let roundBit = false;
    let st: boolean;
    if (top > 52) {
      const shift = top - 52;
      mant = sig >> BigInt(shift);
      roundBit = ((sig >> BigInt(shift - 1)) & 1n) !== 0n;
      st = sticky || (shift > 1 && (sig & ((1n << BigInt(shift - 1)) - 1n)) !== 0n);
    } else {
      mant = sig << BigInt(52 - top);
      st = sticky;
    }
    if (roundBit && (st || (mant & 1n) !== 0n)) {
      mant += 1n;
      if (mant === (1n << 53n)) {
        mant >>= 1n;
        unbiased += 1;
        if (unbiased > 1023) {
          return float64FromBits(sign | 0x7ff0000000000000n);
        }
      }
    }
    return float64FromBits(sign | (BigInt(unbiased + 1023) << 52n) | (mant & 0x000fffffffffffffn));
  }

  const shift = -1074 - exp;
  if (shift > 64) {
    return float64FromBits(sign);
  }
  let mant: bigint;
  let roundBit = false;
  let st: boolean;
  if (shift === 64) {
    mant = 0n;
    roundBit = (sig >> 63n) !== 0n;
    st = sticky || (sig & ((1n << 63n) - 1n)) !== 0n;
  } else if (shift > 0) {
    mant = sig >> BigInt(shift);
    roundBit = ((sig >> BigInt(shift - 1)) & 1n) !== 0n;
    st = sticky || (shift > 1 && (sig & ((1n << BigInt(shift - 1)) - 1n)) !== 0n);
  } else {
    mant = sig << BigInt(-shift);
    st = sticky;
  }
  if (roundBit && (st || (mant & 1n) !== 0n)) {
    mant += 1n;
    if (mant === (1n << 52n)) {
      return float64FromBits(sign | (1n << 52n));
    }
  }
  return float64FromBits(sign | (mant & 0x000fffffffffffffn));
}

function divUint64ToFloat64(neg: boolean, mag: bigint, scale: bigint): number {
  const magTop = 63 - leadingZeros64(mag);
  const scaleTop = 63 - leadingZeros64(scale);
  let s = 54 - (magTop - scaleTop);
  if (s < 0) {
    const q = mag / scale;
    const rem = mag % scale;
    return packFloat64(neg, q, 0, rem !== 0n);
  }
  const limit = scale << 64n;
  for (;;) {
    const dividend = mag << BigInt(s);
    if (dividend >= limit) {
      s -= 1;
      continue;
    }
    const q = dividend / scale;
    const rem = dividend % scale;
    if (q < (1n << 54n)) {
      s += 1;
      continue;
    }
    return packFloat64(neg, q, -s, rem !== 0n);
  }
}

/**
 * Pure-integer signed fixed-point quantization identical to Go's wire.QuantizeFixed.
 */
export function quantizeFixed(v: number, scale: bigint, minInt: bigint, maxInt: bigint): bigint {
  if (scale <= 0n || minInt > maxInt) return 0n;
  const uv = float64Bits(v);
  if (isFloat64NaN(uv)) {
    if (0n < minInt) return minInt;
    if (0n > maxInt) return maxInt;
    return 0n;
  }
  const neg = (uv >> 63n) !== 0n;
  const expField = (uv >> 52n) & 0x7ffn;
  if (expField === 0x7ffn) return neg ? minInt : maxInt;

  const [mag, overflow] = scaledFloat64Mag(uv, scale);
  if (overflow) return neg ? minInt : maxInt;
  if (neg) {
    if (minInt >= 0n) return minInt;
    const minMag = -minInt;
    if (mag >= minMag) return minInt;
    const val = -mag;
    return val > maxInt ? maxInt : val;
  }
  if (maxInt <= 0n) return maxInt;
  if (mag >= maxInt) return maxInt;
  return mag < minInt ? minInt : mag;
}

/**
 * Pure-integer unsigned fixed-point quantization identical to Go's wire.QuantizeFixedUint.
 */
export function quantizeFixedUint(v: number, scale: bigint, maxUint: bigint): bigint {
  if (scale <= 0n) return 0n;
  const uv = float64Bits(v);
  if (isFloat64NaN(uv)) return 0n;
  if ((uv >> 63n) !== 0n) return 0n;
  if (((uv >> 52n) & 0x7ffn) === 0x7ffn) return maxUint;
  const [mag, overflow] = scaledFloat64Mag(uv, scale);
  if (overflow || mag >= maxUint) return maxUint;
  return mag;
}

/**
 * Pure-integer signed fixed-point dequantization identical bit-for-bit to Go's wire.DequantizeFixed.
 */
export function dequantizeFixed(q: bigint, scale: bigint): number {
  if (q === 0n || scale <= 0n) return 0;
  const neg = q < 0n;
  const mag = neg ? -q : q;
  return divUint64ToFloat64(neg, mag, scale);
}

/**
 * Pure-integer unsigned fixed-point dequantization identical bit-for-bit to Go's wire.DequantizeFixedUint.
 */
export function dequantizeFixedUint(q: bigint, scale: bigint): number {
  if (q === 0n || scale <= 0n) return 0;
  return divUint64ToFloat64(false, BigInt.asUintN(64, q), scale);
}
